#!/usr/bin/env python3
from __future__ import annotations

import base64
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
PAYLOAD = json.loads(base64.b64decode("").decode("utf-8"))


def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one occurrence, found {count}")
    return text.replace(old, new, 1)


write("scripts/relaylm_mvp_completion_report_smoke.py", PAYLOAD["completion_script"])

for relative in (
    ".github/workflows/documentation-completion-report-model.yml",
    ".github/workflows/d1-completion-guard-probe.yml",
):
    target = ROOT / relative
    if target.exists():
        target.unlink()

files_workflow = read(".github/workflows/documentation-completion-report-files.yml")
files_workflow = files_workflow.replace(
    "name: Documentation completion report files",
    "name: Transitional completion report files",
    1,
)
if "--self-test" not in files_workflow:
    files_workflow = files_workflow.rstrip() + (
        "\n      - run: python scripts/relaylm_mvp_completion_report_smoke.py --self-test\n"
    )
write(".github/workflows/documentation-completion-report-files.yml", files_workflow)

wave4 = read(".github/workflows/wave4-cross-slice-convergence.yml")
wave4 = wave4.replace(
    "python scripts/relaylm_mvp_completion_report_smoke.py --check-model --check-all",
    "python scripts/relaylm_mvp_completion_report_smoke.py --check-all",
)
if "--check-model" in wave4:
    raise SystemExit("wave4 still invokes --check-model")
write(".github/workflows/wave4-cross-slice-convergence.yml", wave4)

registry = read("scripts/relaylm_mvp_eval_runner_registry.py")
registry = registry.replace(
    '("--check-model", "docs/evidence/implementation/mvp_eval_runner_completion_report.md"),',
    '("docs/evidence/implementation/mvp_eval_runner_completion_report.md",),',
)
if "--check-model" in registry:
    raise SystemExit("MVP eval registry still invokes --check-model")
write("scripts/relaylm_mvp_eval_runner_registry.py", registry)

docs_readme = read("docs/README.md")
docs_readme = docs_readme.replace(
    "[Implementation evidence](evidence/implementation/README.md) — per-PR implementation completion reports and focused historical MVP evidence.",
    "[Implementation evidence](evidence/implementation/README.md) — transitional completion reports and focused historical MVP evidence awaiting D2-D6 disposition.",
)
docs_readme = replace_once(
    docs_readme,
    PAYLOAD["docs_readme_old"],
    PAYLOAD["docs_readme_new"],
    "docs README evidence rule",
)
write("docs/README.md", docs_readme)

evidence_readme = read("docs/evidence/implementation/README.md")
evidence_readme = evidence_readme.replace(
    "  - an implementation evidence record is added, moved, or retired",
    "  - a transitional completion report is repaired, dispositioned, or retired",
    1,
)
evidence_readme = evidence_readme.replace(
    "relaylm_status: current",
    "relaylm_status: compatibility",
    1,
)
start = evidence_readme.find("## Creating a new completion report")
end = evidence_readme.find("\n## Early MVP smoke records", start)
if start < 0 or end < 0:
    raise SystemExit("implementation evidence creation section not found")
evidence_readme = (
    evidence_readme[:start]
    + PAYLOAD["evidence_section_new"]
    + evidence_readme[end:]
)
write("docs/evidence/implementation/README.md", evidence_readme)

templates_readme = read("docs/templates/README.md")
template_line = "- [Implementation completion report](implementation-completion-report.md)\n"
if template_line not in templates_readme:
    raise SystemExit("templates index completion-report link missing")
write("docs/templates/README.md", templates_readme.replace(template_line, "", 1))

template = ROOT / "docs/templates/implementation-completion-report.md"
if not template.exists():
    raise SystemExit("completion-report template is already absent before D1 retirement")
template.unlink()

audit = read("scripts/relaylm_docs_semantic_audit.py")
audit = audit.replace(
    'RETIRED_TEMPLATE_PATHS = ("docs/mvp/IMPLEMENTATION_COMPLETION_REPORT_TEMPLATE.md",)\n',
    "",
)
audit = audit.replace(
    'CANONICAL_COMPLETION_REPORT_TEMPLATE_PATH = "docs/templates/implementation-completion-report.md"\n',
    "",
)
function_start = audit.find("def check_completion_report_template(errors: list[str]) -> None:")
function_end = audit.find("\nMVP_REFERENCE_PATTERN =", function_start)
if function_start < 0 or function_end < 0:
    raise SystemExit("semantic-audit completion-template function block not found")
audit = audit[:function_start] + audit[function_end + 1:]
audit = audit.replace("    check_completion_report_template(errors)\n", "")
audit = audit.replace(PAYLOAD["audit_readme_block"], "")
script_allowlist_start = audit.find(
    '    "scripts/relaylm_mvp_completion_report_smoke.py": ('
)
if script_allowlist_start >= 0:
    script_allowlist_end = audit.find("\n    ),", script_allowlist_start)
    if script_allowlist_end < 0:
        raise SystemExit("semantic-audit completion-report allowlist block is unterminated")
    audit = (
        audit[:script_allowlist_start]
        + audit[script_allowlist_end + len("\n    ),"):]
    )
for forbidden in (
    "check_completion_report_template",
    "CANONICAL_COMPLETION_REPORT_TEMPLATE_PATH",
    "RETIRED_TEMPLATE_PATHS",
    "implementation-completion-report.md",
):
    if forbidden in audit:
        raise SystemExit(f"semantic audit still owns completion template: {forbidden}")
write("scripts/relaylm_docs_semantic_audit.py", audit)

transitional_path = ROOT / "records/documentation/transitional-assets.json"
transitional = json.loads(transitional_path.read_text(encoding="utf-8"))
families = [
    family
    for family in transitional["families"]
    if family.get("family_id") != "legacy-completion-report-validation"
]
families.append(
    {
        "family_id": "legacy-completion-report-validation",
        "paths": sorted(
            [
                ".github/workflows/documentation-completion-report-files.yml",
                "docs/evidence/implementation/README.md",
                "docs/evidence/implementation/*_completion_report.md",
                "scripts/relaylm_mvp_completion_report_smoke.py",
            ]
        ),
        "owner": "documentation",
        "protected_boundary": (
            "Structural integrity of already-committed completion reports: accepted "
            "historical metadata profiles, required sections, concrete source-PR evidence, "
            "and unresolved-placeholder rejection. This family owns no model, template, "
            "current-status, architecture, contract, or new-report creation authority."
        ),
        "current_consumers": sorted(
            [
                ".github/workflows/documentation-completion-report-files.yml",
                ".github/workflows/wave4-cross-slice-convergence.yml",
                ".github/workflows/wave5-cross-slice-convergence.yml",
                "scripts/relaylm_ci_consolidated_smoke.py",
                "scripts/relaylm_mvp_eval_runner_registry.py",
            ]
        ),
        "removal_gate": (
            "Every existing completion report has a reviewed D2-D6 synthesis, allowlisted "
            "record classification, or Git-retirement disposition; no workflow, consolidated "
            "smoke group, current architecture procedure, or operator consumes the validator; "
            "and generic authority, links, record, and Git-recoverability validation protects "
            "every continuing invariant."
        ),
        "replacement_validation": sorted(
            [
                "active_document_authority",
                "git_recoverability",
                "links_and_routers",
                "retained_record_allowlist",
            ]
        ),
        "growth_policy": "closed",
    }
)
transitional["families"] = sorted(families, key=lambda item: item["family_id"])
transitional_path.write_text(
    json.dumps(transitional, indent=2, ensure_ascii=False) + "\n",
    encoding="utf-8",
)

manifest_path = ROOT / "records/documentation/retirement-manifest.json"
manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
entries = [
    entry
    for entry in manifest["entries"]
    if entry.get("old_path") != "docs/templates/implementation-completion-report.md"
]
entries.append(
    {
        "old_path": "docs/templates/implementation-completion-report.md",
        "last_live_commit": "28176f4a8336b6ce7191166e1c720cb71a617e99",
        "old_blob_sha": "f6b1df5d39d0c67b4183ec9b21be302fde81147b",
        "removed_by_pr": 670,
        "replacement_paths": sorted(
            [
                "docs/DOCUMENTATION_MODEL.md",
                "docs/contracts/documentation-governance.md",
            ]
        ),
        "disposition": "superseded",
        "retention_reason": (
            "D1 superseded the reusable per-implementation completion-report creation model "
            "with PR-body evidence and narrowly allowlisted retained records. Existing reports "
            "remain a closed transitional family; the former template is recoverable from Git."
        ),
    }
)
manifest["entries"] = sorted(entries, key=lambda item: item["old_path"])
manifest_path.write_text(
    json.dumps(manifest, indent=2, ensure_ascii=False) + "\n",
    encoding="utf-8",
)

model = read("docs/DOCUMENTATION_MODEL.md")
model = replace_once(
    model,
    PAYLOAD["model_old"],
    PAYLOAD["model_new"],
    "documentation model completion retirement",
)
write("docs/DOCUMENTATION_MODEL.md", model)

contract = read("docs/contracts/documentation-governance.md")
contract = replace_once(
    contract,
    PAYLOAD["contract_marker"],
    PAYLOAD["contract_replacement"],
    "governance completion compatibility",
)
write("docs/contracts/documentation-governance.md", contract)

live_paths = [
    ".github",
    "scripts",
    "docs/README.md",
    "docs/DOCUMENTATION_MODEL.md",
    "docs/evidence/implementation/README.md",
    "docs/templates/README.md",
    "docs/contracts/documentation-governance.md",
]
for relative in live_paths:
    path = ROOT / relative
    candidates = [path] if path.is_file() else [
        candidate for candidate in path.rglob("*") if candidate.is_file()
    ]
    for candidate in candidates:
        try:
            body = candidate.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        if "--check-model" in body:
            raise SystemExit(
                f"live --check-model reference remains: {candidate.relative_to(ROOT)}"
            )
if (ROOT / "docs/templates/implementation-completion-report.md").exists():
    raise SystemExit("retired completion-report template remains")
if (ROOT / ".github/workflows/documentation-completion-report-model.yml").exists():
    raise SystemExit("retired completion-report model workflow remains")
